import { IntentComposer } from '@refy-design/web';
import type { IntentComposerState } from '@refy-design/web';
import type { IntentFilterGroup } from '@refy-design/web';
import type { VoiceRecorderState } from '@refy-design/web';
import { useEffect } from 'react';
import { useRef } from 'react';
import { useState } from 'react';
const initialText =
  'I want to organize reference documents and images for a shared project, with versions and owners.';
const filters: IntentFilterGroup[] = [
  {
    id: 'operation',
    label: 'Operation',
    mode: 'single',
    options: [
      { value: 'create', label: 'Create' },
      { value: 'organize', label: 'Organize' },
    ],
  },
  {
    id: 'types',
    label: 'Format',
    mode: 'multiple',
    options: [
      { value: 'document', label: 'Document' },
      { value: 'image', label: 'Image' },
      { value: 'video', label: 'Video' },
    ],
  },
  {
    id: 'teams',
    label: 'Teams',
    mode: 'multiple',
    options: [
      { value: 'design', label: 'Design' },
      { value: 'product', label: 'Product' },
      { value: 'operations', label: 'Operations' },
    ],
  },
];
function ComposerDemo({ initialState }: { initialState: IntentComposerState }) {
  const [state, setState] = useState<IntentComposerState>(initialState);
  const [voiceState, setVoiceState] = useState<VoiceRecorderState>('listening');
  const [text, setText] = useState(initialText);
  const [filterValues, setFilterValues] = useState<Record<string, string[]>>({
    operation: ['create'],
    types: ['document', 'image'],
    teams: ['design'],
  });
  const [message, setMessage] = useState(`Current state: ${initialState}.`);
  const timer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(timer.current), []);
  function process() {
    setState('processing');
    setMessage('Request in progress.');
    timer.current = window.setTimeout(() => {
      setState('understood');
      setMessage('Request understood and ready for detailed review.');
    }, 1800);
  }
  return (
    <div style={{ display: 'grid', gap: 12, maxWidth: 980 }}>
      <IntentComposer
        state={state}
        filters={filters}
        filterValues={filterValues}
        onFilterValuesChange={setFilterValues}
        value={text}
        onChange={setText}
        examples={[
          'Organize references for a new project',
          'Prepare a collection to share',
        ]}
        understoodSummary="You want a shared collection with documents, images, versions and set owners."
        onSubmit={process}
        onVoiceStart={() => {
          setVoiceState('listening');
          setState('listening');
          setMessage('Voice capture open.');
        }}
        onEditRequest={() => {
          window.clearTimeout(timer.current);
          setState('idle');
          setMessage('Request open for editing.');
        }}
        onEditDetails={() =>
          setMessage('Detailed editing requested for the next wizard step.')
        }
        voiceRecorderProps={{
          state: voiceState,
          duration: 24,
          level: 68,
          onPause: () => setVoiceState('paused'),
          onResume: () => setVoiceState('listening'),
          onCancel: () => {
            setState('idle');
            setMessage('Voice cancelled; text kept.');
          },
          onFinish: () => {
            setState('idle');
            setMessage('Voice done; text ready to correct.');
          },
        }}
      />
      <p
        role="status"
        style={{ margin: 0, color: 'var(--ink-3)', fontSize: 'var(--text-xs)' }}
      >
        {message}
      </p>
    </div>
  );
}
export function Example() {
  return <ComposerDemo initialState="idle" />;
}

